      r'\bis my wudu (?:valid|broken|still)\b',
      r'\b(?:sleep|sleeping|asleep|nap|dozed|dozing|fell asleep|drowsy)\b.*\bwudu\b',
      r'\bwudu\b.*\b(?:sleep|sleeping|asleep|nap|dozed|touch\w*|blood|bleed\w*|vomit\w*|laugh\w*|camel|private part|wind|gas|fart\w*|doubt\w*|unsure|not sure)\b',
      r'\btouch(?:ing)? (?:my |a |the )?(?:private part|genital|penis|woman|wife|husband|spouse)\b.*\b(?:wudu|prayer)\b',
